## 2. Patch Conceitual da Engine

```typescript
// ============================================================================
// CONSTANTES E TABELA DE CICLOS
// ============================================================================
export const BASTIAO_ACTIVE_DURATION_SEC = 15;
export const BASTIAO_DEFAULT_CYCLE_SEC = 35; // 15s ativo + 20s recarga

export const VIP_PVE_CYCLE_TABLE: Record<number, number> = {
  0: 35, // 15s ativo + 20s recarga
  1: 33, // 15s ativo + 18s recarga
  2: 31, // 15s ativo + 16s recarga
  3: 30, // 15s ativo + 15s recarga
};

export const BASTIAO_SHIELD_UNITS = 120;
export const BASTIAO_SHIELD_TOWERS = 180;

// ============================================================================
// CONFIGURAÇÃO SEGURA DO VIP POR PARTIDA (SNAPSHOT)
// ============================================================================
export function configureVipBattle(game: any, tier: number): void {
  // 1. Não aplica em partidas PvP
  if (game.mode === 'pvp') {
    game.vipTier = 0;
    return;
  }

  // 2. Validação estrita de momento: apenas antes do início do combate
  const isGameJustStarted = (!game.nowMs || game.nowMs === 0) &&
                            game.status === 'playing' &&
                            (!game.units || game.units.length === 0);

  if (!isGameJustStarted) {
    // Tentativa tardia ou inválida de injeção de tier: rejeitada silenciosamente
    return;
  }

  // 3. Sanitização do Tier (0 a 3, inteiro, sem perfil.nível direto)
  const safeTier = Number.isInteger(tier) && tier >= 0 && tier <= 3 ? tier : 0;
  game.vipTier = safeTier;
}

// ============================================================================
// HELPER PARA RESOLUÇÃO DE CICLO TOTAL
// ============================================================================
export function getOperatorTotalCycle(game: any, team: 'player' | 'enemy'): number {
  // Inimigo ou partidas PvP sempre utilizam o ciclo padrão
  if (team === 'enemy' || game.mode === 'pvp') {
    return BASTIAO_DEFAULT_CYCLE_SEC;
  }

  const tier = game.vipTier ?? 0;
  return VIP_PVE_CYCLE_TABLE[tier] ?? BASTIAO_DEFAULT_CYCLE_SEC;
}

// ============================================================================
// ATIVAÇÃO DO OPERADOR (BASTIÃO)
// ============================================================================
export function activateOperator(game: any, team: 'player' | 'enemy' = 'player'): boolean {
  if (game.status !== 'playing') return false;

  const isActive = team === 'player' ? (game.playerActive > 0) : (game.enemyActive > 0);
  const isCooldown = team === 'player' ? (game.playerCooldown > 0) : (game.enemyCooldown > 0);

  // Guarda estrita: impede ativação se em recarga OU se já estiver ativo (evita acúmulo)
  if (isCooldown || isActive) {
    return false;
  }

  const cycleDuration = getOperatorTotalCycle(game, team);

  if (team === 'player') {
    game.playerActive = BASTIAO_ACTIVE_DURATION_SEC;
    game.playerCooldown = cycleDuration; // 35s, 33s, 31s ou 30s a partir da ativação
  } else {
    game.enemyActive = BASTIAO_ACTIVE_DURATION_SEC;
    game.enemyCooldown = cycleDuration;
  }

  // Aplicação de escudos em unidades e torres aliadas
  applyBastiaoShields(game, team, BASTIAO_SHIELD_UNITS, BASTIAO_SHIELD_TOWERS);
  return true;
}

// ============================================================================
// TICK DA ENGINE (stepGame)
// ============================================================================
export function stepGame(game: any, dtMs: number): void {
  // Clamp do delta time
  const clampedDtMs = Math.min(Math.max(dtMs, 0), 100);
  const dtSec = clampedDtMs / 1000;

  if (game.status !== 'playing') {
    return;
  }

  game.nowMs = (game.nowMs || 0) + clampedDtMs;

  // 1. Decremento e expiração do efeito Ativo do Jogador
  if (game.playerActive > 0) {
    game.playerActive = Math.max(0, game.playerActive - dtSec);
    if (game.playerActive === 0) {
      removeBastiaoShields(game, 'player');
    }
  }

  // 2. Decremento independente da Recarga do Jogador
  if (game.playerCooldown > 0) {
    game.playerCooldown = Math.max(0, game.playerCooldown - dtSec);
  }

  // 3. Atualizações do Inimigo / PvP
  if (game.mode === 'pvp') {
    // 3a. Decremento e expiração do efeito Ativo do Inimigo
    if (game.enemyActive > 0) {
      game.enemyActive = Math.max(0, game.enemyActive - dtSec);
      if (game.enemyActive === 0) {
        removeBastiaoShields(game, 'enemy');
      }
    }

    // 3b. CORREÇÃO CRÍTICA: Decremento independente da Recarga do Inimigo
    // Não fica aninhado dentro de (enemyActive > 0), garantindo que zere normalmente
    if (game.enemyCooldown > 0) {
      game.enemyCooldown = Math.max(0, game.enemyCooldown - dtSec);
    }
  }

  // Demais lógicas de movimento, combate e torres da engine...
}

// ============================================================================
// HUD STATE E FORMATAÇÃO DE TEXTO
// ============================================================================
export function getHud(game: any) {
  const active = game.playerActive || 0;
  const cooldown = game.playerCooldown || 0;
  const vipTier = game.vipTier || 0;

  let operatorStatusText = 'PRONTO';
  if (active > 0) {
    operatorStatusText = `ATIVO ${Math.ceil(active)}s`;
  } else if (cooldown > 0) {
    operatorStatusText = `RECARGA ${Math.ceil(cooldown)}s`;
  }

  return {
    status: game.status,
    vipTier,
    operatorActive: active,
    operatorCooldown: cooldown,
    operatorStatusText,
    // Demais dados de HUD (torres, elixir, tempo)...
  };
}

// ============================================================================
// BOT / THINK TICK: AUTO-ATIVAÇÃO
// ============================================================================
export function botThinkTick(game: any, team: 'player' | 'enemy'): void {
  const active = team === 'player' ? game.playerActive : game.enemyActive;
  const cooldown = team === 'player' ? game.playerCooldown : game.enemyCooldown;

  // Só ativa se ambos estiverem completamente zerados
  if (active <= 0 && cooldown <= 0) {
    activateOperator(game, team);
  }
}
```

