## 3. Suíte de Testes Unitários Precisos

```typescript
import {
  configureVipBattle,
  activateOperator,
  stepGame,
  getHud,
  botThinkTick,
  BASTIAO_ACTIVE_DURATION_SEC,
  BASTIAO_DEFAULT_CYCLE_SEC,
  VIP_PVE_CYCLE_TABLE
} from './engine';

describe('Frente 2 - Operador Bastião, Ciclos VIP e Correção de Cooldown', () => {
  let game: any;

  beforeEach(() => {
    game = {
      status: 'playing',
      mode: 'pve',
      nowMs: 0,
      units: [],
      towers: [],
      vipTier: 0,
      playerActive: 0,
      playerCooldown: 0,
      enemyActive: 0,
      enemyCooldown: 0,
    };
  });

  // --------------------------------------------------------------------------
  // TESTE 1: Ciclo Base Padrão 35s (15s Ativo + 20s Recarga) e Textos do HUD
  // --------------------------------------------------------------------------
  test('Deve cumprir ciclo padrão de 35s: 15s ativo e 20s recarga com textos de HUD exatos', () => {
    activateOperator(game, 'player');

    expect(game.playerActive).toBe(15);
    expect(game.playerCooldown).toBe(35);

    let hud = getHud(game);
    expect(hud.operatorStatusText).toBe('ATIVO 15s');

    // Avança 10s (em passos de 100ms)
    for (let i = 0; i < 100; i++) stepGame(game, 100);

    expect(game.playerActive).toBeCloseTo(5, 2);
    expect(game.playerCooldown).toBeCloseTo(25, 2);
    hud = getHud(game);
    expect(hud.operatorStatusText).toBe('ATIVO 5s');

    // Avança mais 5s -> completa 15s totais (ativo zera)
    for (let i = 0; i < 50; i++) stepGame(game, 100);

    expect(game.playerActive).toBe(0);
    expect(game.playerCooldown).toBeCloseTo(20, 2);
    hud = getHud(game);
    expect(hud.operatorStatusText).toBe('RECARGA 20s');

    // Avança 20s restantes -> completa 35s totais (recarga zera)
    for (let i = 0; i < 200; i++) stepGame(game, 100);

    expect(game.playerActive).toBe(0);
    expect(game.playerCooldown).toBe(0);
    hud = getHud(game);
    expect(hud.operatorStatusText).toBe('PRONTO');
  });

  // --------------------------------------------------------------------------
  // TESTE 2: Tiers VIP PvE (33s, 31s, 30s)
  // --------------------------------------------------------------------------
  test.each([
    { tier: 1, cycle: 33, recharge: 18 },
    { tier: 2, cycle: 31, recharge: 16 },
    { tier: 3, cycle: 30, recharge: 15 },
  ])('VIP PvE Tier $tier deve configurar ciclo de $cycle s ($recharge s recarga)', ({ tier, cycle, recharge }) => {
    configureVipBattle(game, tier);
    expect(game.vipTier).toBe(tier);

    activateOperator(game, 'player');
    expect(game.playerActive).toBe(15);
    expect(game.playerCooldown).toBe(cycle);

    // Simula término do escudo (15s)
    for (let i = 0; i < 150; i++) stepGame(game, 100);

    expect(game.playerActive).toBe(0);
    expect(game.playerCooldown).toBeCloseTo(recharge, 2);

    const hud = getHud(game);
    expect(hud.operatorStatusText).toBe(`RECARGA ${recharge}s`);
  });

  // --------------------------------------------------------------------------
  // TESTE 3: Isolamento Estrito em PvP (Tier VIP Forçado Não Altera Ciclo)
  // --------------------------------------------------------------------------
  test('Tiers VIP forçados não alteram ciclo em PvP (permanece 35s)', () => {
    game.mode = 'pvp';

    // Tentativa de configurar VIP em partida PvP
    configureVipBattle(game, 3);
    expect(game.vipTier).toBe(0);

    activateOperator(game, 'player');
    expect(game.playerActive).toBe(15);
    expect(game.playerCooldown).toBe(35); // Ciclo inalterado
  });

  // --------------------------------------------------------------------------
  // TESTE 4: Correção Crítica - enemyCooldown Não Fica Eternamente Preso
  // --------------------------------------------------------------------------
  test('Em PvP, enemyCooldown continua decrementando e atinge 0 após enemyActive zerar', () => {
    game.mode = 'pvp';
    activateOperator(game, 'enemy');

    expect(game.enemyActive).toBe(15);
    expect(game.enemyCooldown).toBe(35);

    // Simula 15s -> enemyActive chega a 0
    for (let i = 0; i < 150; i++) stepGame(game, 100);

    expect(game.enemyActive).toBe(0);
    expect(game.enemyCooldown).toBeCloseTo(20, 2);

    // Simula mais 20s -> anteriormente congelava, agora deve zerar
    for (let i = 0; i < 200; i++) stepGame(game, 100);

    expect(game.enemyActive).toBe(0);
    expect(game.enemyCooldown).toBe(0);
  });

  // --------------------------------------------------------------------------
  // TESTE 5: Prevenção de Reativação e Acúmulo de Escudo
  // --------------------------------------------------------------------------
  test('Não permite reativação se operatorActive > 0 mesmo com cooldown zerado artificialmente', () => {
    activateOperator(game, 'player');
    expect(game.playerActive).toBe(15);

    // Força cooldown a zero enquanto ainda ativo
    game.playerCooldown = 0;

    const activatedAgain = activateOperator(game, 'player');
    expect(activatedAgain).toBe(false);
    expect(game.playerActive).toBe(15); // Permanece inalterado, sem empilhamento
  });

  // --------------------------------------------------------------------------
  // TESTE 6: Proteção do Snapshot configureVipBattle (Rejeição Após Início)
  // --------------------------------------------------------------------------
  test('Rejeita configureVipBattle se a partida já iniciou ou possui unidades em campo', () => {
    // Cenário A: nowMs > 0
    game.nowMs = 500;
    configureVipBattle(game, 2);
    expect(game.vipTier).toBe(0);

    // Cenário B: nowMs = 0 mas unidades já existem
    game.nowMs = 0;
    game.units = [{ id: 'u1', team: 'player' }];
    configureVipBattle(game, 3);
    expect(game.vipTier).toBe(0);
  });

  // --------------------------------------------------------------------------
  // TESTE 7: Auto-ativação no Think Tick do Bot (Espera Ambos Zerarem)
  // --------------------------------------------------------------------------
  test('botThinkTick só ativa se active e cooldown forem ambos <= 0', () => {
    // 1. Em combate, inicialmente zerados -> deve ativar
    botThinkTick(game, 'player');
    expect(game.playerActive).toBe(15);
    expect(game.playerCooldown).toBe(35);

    // 2. Chamada imediata em seguida -> não reativa
    botThinkTick(game, 'player');
    expect(game.playerActive).toBe(15);

    // 3. Após 15s (active zerou, cooldown = 20s) -> não pode reativar
    for (let i = 0; i < 150; i++) stepGame(game, 100);
    expect(game.playerActive).toBe(0);
    expect(game.playerCooldown).toBeCloseTo(20, 2);

    botThinkTick(game, 'player');
    expect(game.playerActive).toBe(0); // Não ativou

    // 4. Após mais 20s (ambos zerados) -> reativa com sucesso
    for (let i = 0; i < 200; i++) stepGame(game, 100);
    expect(game.playerCooldown).toBe(0);

    botThinkTick(game, 'player');
    expect(game.playerActive).toBe(15);
    expect(game.playerCooldown).toBe(35);
  });
});
```

